import{_ as t,o as i,c as a,a9 as o}from"./chunks/framework.asyjyako.js";const u=JSON.parse('{"title":"Documentation guide","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/documentation.md","filePath":"contributing/documentation.md","lastUpdated":null}'),s={name:"contributing/documentation.md"};function n(r,e,l,p,c,d){return i(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="Documentation-guide" tabindex="-1">Documentation guide <a class="header-anchor" href="#Documentation-guide" aria-label="Permalink to &quot;Documentation guide {#Documentation-guide}&quot;">​</a></h1><p>Contributions are welcome, from fixing a sentence to adding a reproducible example. Use <strong>Edit this page</strong>, or <a href="https://github.com/Mirage-Interactive-Fr/PerfChecker.jl/issues" target="_blank" rel="noreferrer">open an issue</a>.</p><h2 id="Write-for-someone-trying-the-tool" tabindex="-1">Write for someone trying the tool <a class="header-anchor" href="#Write-for-someone-trying-the-tool" aria-label="Permalink to &quot;Write for someone trying the tool {#Write-for-someone-trying-the-tool}&quot;">​</a></h2><ul><li><p>Introduce the operation before its configuration.</p></li><li><p>Show a runnable example, then explain what it does and how to read the output.</p></li><li><p>Use familiar names: &quot;The worker times the operation&quot; beats &quot;the lifecycle preserves the measurement boundary&quot;.</p></li><li><p>Explain a technical term when it is needed.</p></li><li><p>Keep limitations beside the operation or result they affect.</p></li></ul><p>Put a plot beside each measured comparison, explain its axes, and discuss the values readers can see. Link out for more options. Keep work notes and proposed features out of the user guides.</p><h2 id="Local-build" tabindex="-1">Local build <a class="header-anchor" href="#Local-build" aria-label="Permalink to &quot;Local build {#Local-build}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=website</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; cd(&quot;website&quot;) do; Pkg.develop(path=&quot;..&quot;); Pkg.instantiate(); end&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=website</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> website/make.jl</span></span></code></pre></div><p>Install Node.js 22.12 or newer first. The finished site is <code>website/build/site</code>. Building never deploys.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> website/preview.mjs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # browse the completed site at http://127.0.0.1:8870/</span></span></code></pre></div><p>The build rejects missing references and dead links. The core test suite checks that every exported binding is defined and documented. Review content too: an existing docstring is not proof that its arguments are correct.</p><h2 id="Information-architecture" tabindex="-1">Information architecture <a class="header-anchor" href="#Information-architecture" aria-label="Permalink to &quot;Information architecture {#Information-architecture}&quot;">​</a></h2><ul><li><p><strong>Manual</strong> — from a test to an operation benchmark, then results, suites, comparisons, profiling and CI.</p></li><li><p><strong>Examples</strong> — complete experiments for Bibliography, DataStructures and Oxygen.</p></li><li><p><strong>Interfaces</strong> — controls and setup for each UI.</p></li><li><p><strong>Further topics</strong> — additional measurements, larger experiments, remote execution and optional advisors.</p></li><li><p><strong>Reference</strong> — arguments, formats and integration details.</p></li><li><p><strong>Contributing</strong> — architecture, collection tests and documentation.</p></li></ul><p>Keep each detailed explanation in one place and link to it elsewhere. The sidebar order comes from <code>website/make.jl</code>; update it when moving a chapter.</p><p>Before adding a code block, say whether it is a complete runnable example, a fragment using earlier variables, or a format illustration. Give the working directory and prerequisites, and name placeholder paths explicitly.</p><p>Do not present a planned collector, platform or attribution method as implemented.</p><h2 id="Explain-a-measurement-before-configuring-it" tabindex="-1">Explain a measurement before configuring it <a class="header-anchor" href="#Explain-a-measurement-before-configuring-it" aria-label="Permalink to &quot;Explain a measurement before configuring it {#Explain-a-measurement-before-configuring-it}&quot;">​</a></h2><p>Introduce every collector with one or two paragraphs: the question it answers, the quantity and unit it records, and how to read the result. Define terms such as wall time, GC and flame graph at first use.</p><ul><li><p>Version comparisons need several actual revisions with input and dependency provenance. A distribution from one version only shows sampling variation.</p></li><li><p>Distinguish declared package versions, Git tags and later commits.</p></li><li><p>Explain unavailable workloads and failed preparation; never replace them with zero.</p></li><li><p>When two collectors expose similarly named fields, explain the difference locally (BenchmarkTools GC time vs Chairmarks GC fraction).</p></li></ul><h2 id="Screenshots" tabindex="-1">Screenshots <a class="header-anchor" href="#Screenshots" aria-label="Permalink to &quot;Screenshots {#Screenshots}&quot;">​</a></h2><p>Store images under <code>website/src/public/assets/screenshots/&lt;interface&gt;/</code>. Use actual application output only.</p><ol><li><p>Capture a fixed, readable desktop size; add a narrow layout when responsive behavior matters.</p></li><li><p>Remove tokens, private endpoints, usernames, absolute local paths and private package data.</p></li><li><p>Use stable demo bundles so screenshots can be regenerated.</p></li><li><p>Provide descriptive alt text and a caption explaining the user outcome.</p></li><li><p>Prefer SVG for diagrams, PNG/WebP for UI, static Makie export for plots.</p></li><li><p>Verify light and dark themes when the component supports them.</p></li><li><p>Refresh images when labels or flows change, not every release.</p></li></ol><h2 id="Recordings" tabindex="-1">Recordings <a class="header-anchor" href="#Recordings" aria-label="Permalink to &quot;Recordings {#Recordings}&quot;">​</a></h2><p>Keep source recordings outside Git history. The local archive is <code>.lab/media/&lt;recording&gt;/</code>; <code>website/.gitignore</code> also excludes WebM, MP4 and MOV copies.</p><p>For publication, use an approved project recording on YouTube and set its <code>youtube_id</code> in <code>website/media.json</code>. The site loads the privacy-enhanced player only after a reader clicks the poster. This does not make YouTube tracker-free.</p><h2 id="Pull-request-checklist" tabindex="-1">Pull-request checklist <a class="header-anchor" href="#Pull-request-checklist" aria-label="Permalink to &quot;Pull-request checklist {#Pull-request-checklist}&quot;">​</a></h2><ul><li><p>build DocumenterVitepress locally;</p></li><li><p>check internal and external links;</p></li><li><p>run doctests and any TestItems the examples affect;</p></li><li><p>verify screenshots at their rendered size;</p></li><li><p>state which commands passed and which integrations you did not exercise.</p></li></ul><p><a id="Screenshot-policy"></a><a id="Recordings-outside-Git"></a></p>`,27)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
